package com.garagedesk.entity;
import jakarta.persistence.*; import jakarta.validation.constraints.NotBlank; import java.time.LocalDateTime;
@Entity @Table(name="job_cards") public class JobCard { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(optional=false) @JoinColumn(name="vehicle_id") Vehicle vehicle; @ManyToOne @JoinColumn(name="mechanic_id") Mechanic mechanic; @ManyToOne @JoinColumn(name="bay_id") ServiceBay bay; @NotBlank String requestedServices; String customerComplaint; String workDescription; LocalDateTime scheduledStart; LocalDateTime scheduledEnd; @Enumerated(EnumType.STRING) JobStatus status=JobStatus.WAITING; double partsAmount; double labourCharge; public JobCard(){} public Long getId(){return id;} public Vehicle getVehicle(){return vehicle;} public void setVehicle(Vehicle v){vehicle=v;} public Mechanic getMechanic(){return mechanic;} public void setMechanic(Mechanic v){mechanic=v;} public ServiceBay getBay(){return bay;} public void setBay(ServiceBay v){bay=v;} public String getRequestedServices(){return requestedServices;} public void setRequestedServices(String v){requestedServices=v;} public String getCustomerComplaint(){return customerComplaint;} public void setCustomerComplaint(String v){customerComplaint=v;} public String getWorkDescription(){return workDescription;} public void setWorkDescription(String v){workDescription=v;} public LocalDateTime getScheduledStart(){return scheduledStart;} public void setScheduledStart(LocalDateTime v){scheduledStart=v;} public LocalDateTime getScheduledEnd(){return scheduledEnd;} public void setScheduledEnd(LocalDateTime v){scheduledEnd=v;} public JobStatus getStatus(){return status;} public void setStatus(JobStatus v){status=v;} public double getPartsAmount(){return partsAmount;} public void setPartsAmount(double v){partsAmount=v;} public double getLabourCharge(){return labourCharge;} public void setLabourCharge(double v){labourCharge=v;} }
